/bin/zsh -lc "python3 -B -c '
import copy
import platform
import runpy
from contextlib import contextmanager

consume = runpy.run_path('\\''project/consumer.py'\\'')['\\''consume'\\'']

class DB:
    def __init__(self):
        self.accounts = {}
        self.audits = []
        self.quarantine = []
    @contextmanager
    def transaction(self):
        saved = copy.deepcopy((self.accounts, self.audits, self.quarantine))
        try:
            yield
        except BaseException:
            self.accounts, self.audits, self.quarantine = saved
            raise
    def set_account(self, key, revision, tier):
        self.accounts[key] = {'\\''revision'\\'': revision, '\\''tier'\\'': tier}
    def insert_audit(self, event_id):
        self.audits.append(event_id)
    def apply_if_newer(self, event):
        current = self.accounts.get(event['\\''account_id'\\''])
        if current is not None and event['\\''revision'\\''] <= current['\\''revision'\\'']:
            return False
        self.set_account(event['\\''account_id'\\''], event['\\''revision'\\''], event['\\''tier'\\''])
        return True

class Delivery:
    def __init__(self, fail=False):
        self.fail = fail
        self.acked = False
    def ack(self):
        if self.fail:
            raise ConnectionError('\\''injected lost acknowledgement after commit'\\'')
        self.acked = True

def proposed(event, db, delivery):
    required = ('\\''event_id'\\'', '\\''account_id'\\'', '\\''revision'\\'', '\\''tier'\\'')
    if not all(key in event for key in required):
        with db.transaction():
            db.quarantine.append(copy.deepcopy(event))
    else:
        with db.transaction():
            if db.apply_if_newer(event):
                db.insert_audit(event['\\''event_id'\\''])
    delivery.ack()

e12 = {'\\''event_id'\\'': '\\''e12'\\'', '\\''account_id'\\'': '\\''a'\\'', '\\''revision'\\'': 12, '\\''tier'\\'': '\\''gold'\\''}
e11 = {'\\''event_id'\\'': '\\''e11'\\'', '\\''account_id'\\'': '\\''a'\\'', '\\''revision'\\'': 11, '\\''tier'\\'': '\\''silver'\\''}
history = [e12, e12, e11]
print('\\''Runtime:'\\'', platform.python_version())
for label, handler in [('\\''supplied consumer'\\'', consume), ('\\''proposed atomic guard model'\\'', proposed)]:
    db = DB()
    deliveries = [Delivery() for _ in history]
    for event, delivery in zip(history, deliveries):
        handler(event, db, delivery)
    expected = {'\\''revision'\\'': 11, '\\''tier'\\'': '\\''silver'\\''} if handler is consume else {'\\''revision'\\'': 12, '\\''tier'\\'': '\\''gold'\\''}
    assert db.accounts['\\''a'\\''] == expected
    assert db.audits == (['\\''e12'\\'', '\\''e12'\\'', '\\''e11'\\''] if handler is consume else ['\\''e12'\\''])
    print(label, {'\\''account'\\'': db.accounts['\\''a'\\''], '\\''audits'\\'': db.audits, '\\''acknowledgements'\\'': sum(d.acked for d in deliveries)})

for label, handler in [('\\''supplied consumer'\\'', consume), ('\\''proposed atomic guard model'\\'', proposed)]:
    db = DB()
    try:
        handler(e12, db, Delivery(fail=True))
    except ConnectionError:
        pass
    assert db.accounts['\\''a'\\''] == {'\\''revision'\\'': 12, '\\''tier'\\'': '\\''gold'\\''}
    retry = Delivery()
    handler(e12, db, retry)
    assert db.audits == (['\\''e12'\\'', '\\''e12'\\''] if handler is consume else ['\\''e12'\\''])
    print(label + '\\'' after commit/ack failure and redelivery'\\'', {'\\''account'\\'': db.accounts['\\''a'\\''], '\\''audits'\\'': db.audits, '\\''acknowledgements'\\'': int(retry.acked)})

malformed = {'\\''event_id'\\'': '\\''bad'\\'', '\\''account_id'\\'': '\\''a'\\'', '\\''revision'\\'': 13}
for label, handler in [('\\''supplied consumer'\\'', consume), ('\\''proposed atomic guard model'\\'', proposed)]:
    db = DB()
    delivery = Delivery()
    error = None
    try:
        handler(malformed, db, delivery)
    except KeyError as exc:
        error = str(exc)
    assert not db.accounts and not db.audits
    assert delivery.acked == (handler is proposed)
    assert len(db.quarantine) == (1 if handler is proposed else 0)
    print(label + '\\'' malformed record'\\'', {'\\''error'\\'': error, '\\''quarantine_records'\\'': len(db.quarantine), '\\''acknowledgements'\\'': int(delivery.acked)})

class FailingAuditDB(DB):
    def insert_audit(self, event_id):
        raise RuntimeError('\\''injected audit failure'\\'')
for label, handler in [('\\''supplied consumer'\\'', consume), ('\\''proposed atomic guard model'\\'', proposed)]:
    db = FailingAuditDB()
    delivery = Delivery()
    try:
        handler(e12, db, delivery)
    except RuntimeError:
        pass
    assert not db.accounts and not db.audits and not delivery.acked
    print(label + '\\'' audit failure'\\'', {'\\''accounts'\\'': db.accounts, '\\''audits'\\'': db.audits, '\\''acknowledgements'\\'': 0})
print('\\''Model checks passed; no broker, database, or concurrency integration was exercised.'\\'')
